starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "rule_name" {
  description = "Input variable rule_name."
  type        = string
  default     = "nightly-job"
}

variable "lambda_role_arn" {
  description = "Input variable lambda_role_arn."
  type        = string
}

variable "lambda_runtime" {
  description = "Input variable lambda_runtime."
  type        = string
  default     = "python3.12"
}

variable "lambda_memory" {
  description = "Input variable lambda_memory."
  type        = number
  default     = 128
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_cloudwatch_event_rule" "this" {
  name                = "app-rule"
  schedule_expression = "rate(5 minutes)"
}

resource "aws_cloudwatch_event_target" "this" {
  rule  = aws_cloudwatch_event_rule.this.name
  arn   = aws_lambda_function.this.arn
  input = jsonencode({})
}

resource "aws_lambda_function" "this" {
  # TODO - Complete the scheduled function.
  # Configure the function runtime, handler, role and memory for the scheduled job.
}

resource "aws_lambda_permission" "this" {
  statement_id  = "allow-apigw"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.this.function_name
  principal     = "apigateway.amazonaws.com"
}

starter.outputs.tf:
output "rule_arn" {
  value = aws_cloudwatch_event_rule.this.arn
}

output "lambda_arn" {
  value = aws_lambda_function.this.arn
}
